import re

def parse_duration(s: str) -> int:
    """
    Converts a duration string (e.g., '1h30m15s', '45s', '2h', '10m') to total seconds.
    """
    if not s:
        raise ValueError("Input duration string cannot be empty.")

    # Regex to find all numbers followed by a valid unit (h, m, or s)
    # The 's' flag makes the regex case-insensitive, but units are usually lowercase.
    matches = re.findall(r'(\d+)([smh])', s)

    if not matches:
        # If the string is not empty but no units are found (e.g., 'abc'), it's invalid.
        if s.strip():
            raise ValueError("Invalid duration format. Units (h, m, s) required.")
        # This case should ideally be caught by 'if not s' above, but included for robustness.
        raise ValueError("Invalid duration format.")

    total_seconds = 0
    for value_str, unit in matches:
        try:
            value = int(value_str)
        except ValueError:
            # Should not happen if regex only captures digits
            raise ValueError("Invalid numerical value in duration string.")

        if unit == 'h':
            total_seconds += value * 3600
        elif unit == 'm':
            total_seconds += value * 60
        elif unit == 's':
            total_seconds += value
        else:
            # Should not happen based on regex
            raise ValueError(f"Invalid unit encountered: {unit}")

    return total_seconds
