    def is_business_day(dt: date) -> bool:
        # Monday=0, Friday=4
        is_weekday = dt.weekday() < 5
        is_not_holiday = dt not in holidays
        return is_weekday and is_not_holiday

    # Case n == 0
    if n == 0:
        if is_business_day(d):
            return d
        else:
            # Find the next business day
            current = d
            while not is_business_day(current):
                current += timedelta(days=1)
            return current

    if n > 0:
        # Moving forward
        count = 0
        current = d
        while count < n:
            current += timedelta(days=1)
            if is_business_day(current):
                count += 1
        return current

    else:
        # Moving backward (n is negative)
        count = 0
        current = d
        while count > n:
            current -= timedelta(days=1)
            if is_business_day(current):
                count -= 1
        return current
