def compact(n: int) -> str:
    if n < 1000:
        return str(n)

    # Units are powers of 1000: 10^3, 10^6, 10^9
    units = [('bi', 1_000_000_000), ('mi', 1_000_000), ('mil', 1_000)]

    # Find the largest unit applicable (starting from billions down)
    for unit, divisor in units:
        value = n / divisor

        # Custom rounding function: round half up to 1 decimal place
        # Standard Python round() uses round half to even. We need round half up.
        # For x = I + F, we want (I + 0.5*1) if F >= 0.5.

        if value < 1:
            continue # Not enough magnitude for this unit

        # Rounding logic for 'half up' to one decimal place:
        # Multiply by 10, add 0.5, floor, then divide by 10.0
        rounded_value = int(value * 10.0 + 0.5) / 10.0

        # Check if rounding the current unit makes the value >= 1.0
        # If it rounds up to exactly the next integer (e.g., 0.95 -> 1.0), 
        # we must use the next larger unit, as per the rule (999950 -> '1 mi').

        # Re-calculate the number if it rounds to 1.0, to see if the next unit is better
        rounded_int = int(rounded_value)

        if rounded_int > 0 and rounded_value >= 1.0:
            # If the value is 1.0 or greater, this unit is valid
            break

        # Special case for the last unit ('mil'): if it rounds up to 1, it's fine.
        if unit == 'mil' and rounded_value >= 1.0:
             break

    else:
        # Should not happen if n >= 1000, but safety check
        return str(n)

    # Post-processing for string formatting

    # Format to remove trailing ',0'
    if rounded_value == int(rounded_value):
        result = str(int(rounded_value)) + ' ' + unit
    else:
        result = f"{rounded_value:.1f} {unit}"

    return result.replace('.', ',').strip()
