import heapq

def build_order(deps: dict[str, list[str]]) -> list[str]:
    """
    build_order(deps) -> list[str] returns an order in which every item comes after the items it depends on.
    Among the items that are ready at the same time, take the alphabetically smallest first.
    """

    # 1. Identify all nodes and initialize graph structures
    all_items = set(deps.keys())
    for dependencies in deps.values():
        for dep in dependencies:
            all_items.add(dep)

    adj = {item: [] for item in all_items}
    in_degree = {item: 0 for item in all_items}

    # 2. Build the graph (Dependency -> Dependent) and calculate in-degrees
    for dependent, dependencies in deps.items():
        for dependency in dependencies:
            adj[dependency].append(dependent)
            in_degree[dependent] += 1

    # 3. Initialize the ready queue (Min-heap ensures alphabetical sorting)
    ready_queue = []
    for item in all_items:
        if in_degree[item] == 0:
            heapq.heappush(ready_queue, item)

    result = []

    # 4. Process items using Kahn's algorithm
    while ready_queue:
        # Get the alphabetically smallest item ready
        current_item = heapq.heappop(ready_queue)
        result.append(current_item)

        # Process neighbors (items that depend on the current_item)
        for neighbor in adj[current_item]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                heapq.heappush(ready_queue, neighbor)

    # 5. Cycle detection
    if len(result) != len(all_items):
        raise ValueError("A cycle exists in the dependencies.")

    return result
