from collections import OrderedDict

def latest_by_key(records: list[dict], key: str) -> list[dict]:
    # Stores the best record found so far for each key value
    # Structure: {key_value: {'record': dict, 'timestamp': datetime, 'index': int}}
    candidates = {}

    # Stores the order in which the key values first appeared
    first_occurrence_order = []

    for index, record in enumerate(records):
        try:
            key_value = record[key]
            updated_at_str = record['updated_at']

            # Parse the ISO 8601 timestamp. fromisoformat handles offsets (Z, +02:00) correctly.
            current_time = datetime.fromisoformat(updated_at_str)
        except (KeyError, ValueError):
            # Skip records missing the key or having a malformed timestamp
            continue

        if key_value not in candidates:
            # First time seeing this key value
            first_occurrence_order.append(key_value)
            candidates[key_value] = {
                'record': record,
                'timestamp': current_time,
                'index': index
            }
        else:
            # Compare against the current best candidate
            current_best = candidates[key_value]

            # Comparison logic:
            # 1. Higher timestamp is newer (latest).
            # 2. On a tie (timestamps are equal), the record appearing later in the list (higher index) wins.

            if current_time > current_best['timestamp']:
                # New record is strictly newer
                candidates[key_value] = {
                    'record': record,
                    'timestamp': current_time,
                    'index': index
                }
            elif current_time == current_best['timestamp'] and index > current_best['index']:
                # Tie in time, but new record appears later in the input list
                candidates[key_value] = {
                    'record': record,
                    'timestamp': current_time,
                    'index': index
                }

    # Construct the result based on the order of first appearance
    result = []
    for key_value in first_occurrence_order:
        result.append(candidates[key_value]['record'])

    return result
