from collections import defaultdict

def build_order(deps: dict[str, list[str]]) -> list[str]:
    all_items = set(deps.keys())
    for deps_list in deps.values():
        all_items.update(deps_list)

    # Initialize in-degrees and adjacency list
    in_degree = {item: 0 for item in all_items}
    # adj maps an item to the list of items that depend on it
    adj = {item: [] for item in all_items}

    # Populate graph structures
    for item, dependencies in deps.items():
        for dep in dependencies:
            # Item depends on dep. So, dep -> item is an edge
            adj[dep].append(item)
            in_degree[item] += 1

    # Priority queue stores items ready to be built, ordered alphabetically
    pq = []
    for item in all_items:
        if in_degree[item] == 0:
            heapq.heappush(pq, item)

    build_order_list = []
    while pq:
        # Pop the alphabetically smallest item (due to min-heap property)
        current = heapq.heappop(pq)
        build_order_list.append(current)

        # Process neighbors (items that depend on the current item)
        for neighbor in adj[current]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                heapq.heappush(pq, neighbor)

    if len(build_order_list) != len(all_items):
        raise ValueError("A cycle exists in the dependencies.")

    return build_order_list
