import math

def is_not_prime(n):
    """
    Identifies non-prime numbers. Returns False if n is prime, True otherwise.
    Assumes input n is an integer.
    """
    if n <= 1:
        return True

    if n == 2:
        return False

    if n % 2 == 0:
        return True

    limit = int(math.sqrt(n)) + 1
    for i in range(3, limit, 2):
        if n % i == 0:
            return True

    # If no divisors were found, the number is prime
    return False
