import heapq

def heap_queue_largest(nums, n):
    """
    Finds the n largest integers from a given list of numbers using a min-heap.
    Returns the result in descending order.
    """
    min_heap = []

    for num in nums:
        if len(min_heap) < n:
            heapq.heappush(min_heap, num)
        else:
            # If the current number is larger than the smallest element in the heap (root), 
            # replace the smallest element with the current number.
            if num > min_heap[0]:
                heapq.heapreplace(min_heap, num)

    # The min_heap now contains the n largest elements.
    # We sort them in descending order for the final output.
    return sorted(min_heap, reverse=True)
