def is_woodall(n: int) -> bool:
    """
    Checks if the given number is a Woodall number.
    A Woodall number W_n is defined as W_n = (n(n+1)/2) * 2^(n-1) - 1 for n >= 1.
    """
    if n < 0:
        return False

    # Calculate the value for increasing n until we meet or exceed n
    # The formula is W_n = (n*(n+1)//2) * (2**(n-1)) - 1
    n_test = 1
    while True:
        # Calculate the potential Woodall number W_{n_test}
        try:
            woodall_number = ((n_test * (n_test + 1)) // 2) * (2**(n_test - 1)) - 1
        except OverflowError:
            # Handle potential overflow for very large numbers
            return False

        if woodall_number == n:
            return True

        if woodall_number > n:
            # Since the sequence is strictly increasing, if we exceeded n, 
            # n is not a Woodall number.
            return False

        n_test += 1
